add_action('wp_loaded', function(){
  if(!isset($_GET['ps_find']) || $_GET['ps_find']!=='Findx') return;
  while(ob_get_level()) ob_end_clean();
  global $wpdb; $o=array();
  $t=$wpdb->prefix.'snippets';
  if($wpdb->get_var("SHOW TABLES LIKE '$t'")){
    $rows=$wpdb->get_results("SELECT id,name,active,LENGTH(code) len FROM $t
      WHERE code LIKE '%canonical_table_hash%' OR code LIKE '%chash_v1%' ORDER BY id DESC LIMIT 10",ARRAY_A);
    $o['snippetai']=$rows;
    if($rows){
      $code=$wpdb->get_var($wpdb->prepare("SELECT code FROM $t WHERE id=%d",$rows[0]['id']));
      $i=strpos($code,'canonical_table_hash');
      if($i===false) $i=strpos($code,'chash_v1');
      $o['fragmentas']=substr($code,max(0,$i-1500),2500);
    }
  }
  // ir MU pluginuose
  $hits=array();
  foreach(array(WPMU_PLUGIN_DIR, WP_PLUGIN_DIR.'/petshop-core') as $d){
    if(!is_dir($d)) continue;
    foreach(glob($d.'/*.php') as $f){
      $c=@file_get_contents($f);
      if($c && (strpos($c,'canonical_table_hash')!==false || strpos($c,'chash_v1')!==false)) $hits[]=basename($f);
    }
    foreach(glob($d.'/*/*.php') as $f){
      $c=@file_get_contents($f);
      if($c && (strpos($c,'canonical_table_hash')!==false || strpos($c,'chash_v1')!==false)) $hits[]=str_replace($d.'/','',$f);
    }
  }
  $o['failai']=$hits;
  header('Content-Type: application/json'); echo json_encode($o); exit;
});
